--
-- Table structure for table `productattribute`
--

DROP TABLE IF EXISTS `productattribute`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `productattribute` (
  `id` int NOT NULL AUTO_INCREMENT,
  `productId` int NOT NULL,
  `attributeId` int NOT NULL,
  `attributeValueId` int NOT NULL,
  `attributeName` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `attributeValueName` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ProductAttribute_productId_attributeId_attributeValueId_key` (`productId`,`attributeId`,`attributeValueId`),
  KEY `ProductAttribute_attributeName_attributeValueName_idx` (`attributeName`,`attributeValueName`),
  KEY `ProductAttribute_attributeId_fkey` (`attributeId`),
  KEY `ProductAttribute_attributeValueId_fkey` (`attributeValueId`),
  CONSTRAINT `ProductAttribute_attributeId_fkey` FOREIGN KEY (`attributeId`) REFERENCES `attribute` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ProductAttribute_attributeValueId_fkey` FOREIGN KEY (`attributeValueId`) REFERENCES `attributevalue` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ProductAttribute_productId_fkey` FOREIGN KEY (`productId`) REFERENCES `product` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8370 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

